schema_ddl:
CREATE DOMAIN tipo_operazione AS TEXT CHECK (VALUE IN ('versamento', 'prelievo', 'bonifico_entrata', 'bonifico_uscita', 'commissione', 'accredito'));

CREATE DOMAIN importo_non_negativo AS NUMERIC(14,2) CHECK (VALUE >= 0);

CREATE TABLE clienti (
    id INT PRIMARY KEY,
    nome TEXT NOT NULL,
    codice_fiscale TEXT NOT NULL UNIQUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE conti (
    id INT PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    iban TEXT NOT NULL UNIQUE,
    saldo_disponibile NUMERIC(14,2) NOT NULL CHECK (saldo_disponibile >= 0),
    data_apertura DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE transazioni (
    id BIGINT PRIMARY KEY,
    conto_id INT NOT NULL REFERENCES conti(id),
    tipo_operazione tipo_operazione NOT NULL,
    importo importo_non_negativo NOT NULL,
    data_transazione TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    descrizione TEXT
);

CREATE TABLE prestiti (
    id INT PRIMARY KEY,
    cliente_id INT NOT NULL REFERENCES clienti(id),
    importo_capitale importo_non_negativo NOT NULL,
    tasso_interesse NUMERIC(5,2) NOT NULL CHECK (tasso_interesse >= 0),
    data_erogazione DATE NOT NULL,
    data_scadenza DATE NOT NULL,
    CHECK (data_scadenza > data_erogazione)
);
